DELETE FROM gold.fact_facturacion;
DELETE FROM gold.fact_admisiones;
DELETE FROM gold.dim_diagnostico;
DELETE FROM gold.dim_servicio_cargo;
DELETE FROM gold.dim_departamento;
DELETE FROM gold.dim_paciente;
DELETE FROM gold.dim_fecha;

DECLARE @ini DATE, @fin DATE;
SELECT @ini = MIN(f), @fin = MAX(f) FROM (
    SELECT admission_date AS f FROM silver.admissions
    UNION ALL SELECT discharge_date FROM silver.admissions
    UNION ALL SELECT payment_date FROM silver.billing) t WHERE f IS NOT NULL;
SET @ini = DATEFROMPARTS(YEAR(@ini),1,1);
SET @fin = DATEFROMPARTS(YEAR(@fin),12,31);

WITH n AS (SELECT TOP (DATEDIFF(DAY,@ini,@fin)+1) ROW_NUMBER() OVER (ORDER BY (SELECT NULL))-1 AS i
           FROM sys.all_objects a CROSS JOIN sys.all_objects b)
INSERT INTO gold.dim_fecha (fecha_key, fecha_completa, anio, trimestre, trimestre_nombre, mes, mes_nombre, mes_corto,
                            semana_anio, dia_mes, dia_semana, dia_nombre, es_fin_de_semana)
SELECT YEAR(x.f)*10000+MONTH(x.f)*100+DAY(x.f), x.f, YEAR(x.f), DATEPART(QUARTER,x.f),
       'T'+CAST(DATEPART(QUARTER,x.f) AS VARCHAR(1)), MONTH(x.f),
       CHOOSE(MONTH(x.f),'Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'),
       CHOOSE(MONTH(x.f),'Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'),
       DATEPART(ISO_WEEK,x.f), DAY(x.f), y.ds,
       CHOOSE(y.ds,'Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'),
       CASE WHEN y.ds >= 6 THEN 1 ELSE 0 END
FROM n
CROSS APPLY (SELECT DATEADD(DAY,n.i,@ini) AS f) x
CROSS APPLY (SELECT ((DATEPART(WEEKDAY,x.f)+@@DATEFIRST-2)%7)+1 AS ds) y;

SET IDENTITY_INSERT gold.dim_diagnostico ON;
INSERT INTO gold.dim_diagnostico (diagnostico_key, codigo_icd, descripcion_patologia, nivel_severidad)
VALUES (-1, 'N/A', 'Sin diagnóstico', 'Unknown');
SET IDENTITY_INSERT gold.dim_diagnostico OFF;

DELETE FROM silver.billing;
DELETE FROM silver.diagnoses;
DELETE FROM silver.admissions;
DELETE FROM silver.patients;
